-- Arrival delay deciles per event type: how long truth takes to land.
-- snowflake dialect. Generated by tools/emit_sql.py; `make sql` regenerates.
WITH delays AS (
    SELECT
        event_type,
        arrival_days - fact_days AS delay_days,
        NTILE(10) OVER (
            PARTITION BY event_type
            ORDER BY arrival_days - fact_days
        ) AS decile
    FROM events
)
SELECT
    event_type,
    decile,
    COUNT(*) AS rows_in_decile,
    MIN(delay_days) AS delay_from_days,
    MAX(delay_days) AS delay_to_days
FROM delays
GROUP BY event_type, decile
ORDER BY event_type, decile
